groupCohomology.mem_twoCocycles_def.code:
groupCohomology.mem_twoCocycles_def.{u} {k G : Type u} [CommRing k] [Group G] {A : Rep k G}
  (f : G × G → CoeSort.coe A) :
  f ∈ twoCocycles A ↔ ∀ (g h j : G), (A.ρ g) (f (h, j)) - f (g * h, j) + f (g, h * j) - f (g, h) = 0

groupCohomology.mem_twoCocycles_iff.code:
groupCohomology.mem_twoCocycles_iff.{u} {k G : Type u} [CommRing k] [Group G] {A : Rep k G}
  (f : G × G → CoeSort.coe A) :
  f ∈ twoCocycles A ↔ ∀ (g h j : G), f (g * h, j) + f (g, h) = (A.ρ g) (f (h, j)) + f (g, h * j)
